import{z as l,x as s,o as e,c as d,q as B,j as n,D as A,d as t,s as i,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"监管义务与收束","description":"","frontmatter":{"title":"监管义务与收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mm-regulation-map.md","filePath":"quant/mm-regulation-map.md","lastUpdated":1791063341000}'),p={name:"quant/mm-regulation-map.md"};function m(D,E,u,h,F,C){const r=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=B('<h1 id="监管义务与收束" tabindex="-1">监管义务与收束 <a class="header-anchor" href="#监管义务与收束" aria-label="Permalink to &quot;监管义务与收束&quot;">​</a></h1><div class="epigraph"><p>市场用激励换供给：回扣、费用减免与地位换来价差、在市与规模义务；做市的自由，从来是合同内的自由。</p><footer>—— 据 Harris, Trading and Exchanges, 2003 与各交易所做市义务文本整理</footer></div><p><a href="/quant/mm-pnl-attribution">上一课</a>把损益拆到机制并回馈参数。到此为止，做市都在与市场博弈；但挂牌本身是一份合同：激励换义务与红线。本课写监管义务如何进引擎，并收束本课程。本课程到此收束：策略（参数、偏移、对冲、对手方）、风控（毒性、限额、降风险）到运营（跨品种、归因、义务），前九课的对象在这里以「约束」的身份再出现一次。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>义务做市合同的典型条款：最大报价价差、最小挂单量、在市时间比例、参与率上下限、最小报价改进。红线：虚假流动性（申报后撤销以制造深度假象）、误导性展示、抢跑客户订单与信息滥用。缺口有两个：义务如何不与毒性防御打架——检测器喊停时，在市义务不允许你消失；违规证据如何自证——你需要能回答「每一笔撤单为什么撤」。</p><h3 id="义务进引擎" tabindex="-1">义务进引擎 <a class="header-anchor" href="#义务进引擎" aria-label="Permalink to &quot;义务进引擎&quot;">​</a></h3><p>义务作为硬约束进报价引擎，与<a href="/quant/mm-risk-limits">做市风控与限额</a>同一接口：在市率、宽度上限、规模下限都是预检规则。毒性触发高档动作时，引擎在义务允许的角落里选择：收窄到义务宽度的下限、只保最小规模、单侧停而另一侧守义务——第五课动作分级要留这些中间档，原因正在于此：义务把「全跑」从合法选项里拿走了一部分。</p><p><span class="marginnote">「义务做市合同」就是交易所和你签的对价协议：它付你好处（回扣、手续费减免、「指定做市商」地位），换你三件事——报价别离谱（最大价差）、别缺席（在市时间比例）、别只挂一手（最小挂单量）。这不是荣誉头衔，是写进报价引擎的硬约束，违反了轻则取消地位、重则追责。</span></p><p><span class="marginnote">同一条撤单流有两个读者：做市商读作「切短逆向选择窗口」，监管读作「是否虚假流动性」。意图的推断靠挂撤比、挂撤时序与报价距离；能自证的只有 L3 订单日志与改单原因码——这是合规基础设施，不是可选项。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>监控与留痕三件事：日报（在市率、宽度合规率、撤单率与改单原因分布，撤单率口径见 <a href="/quant/cancel-rate">撤单速率</a>）；L3 订单生命周期日志全量留存，每笔撤单可回放当时簿态与决策理由；策略与合规的联合评审进研究台账，与<a href="/quant/research-postmortem">研究复盘</a>同一模板——义务违约与策略亏损同权归档。制度差异要有对照表：美国注册做市商义务、欧盟 MiFID II 的报备与订单成交比控制、中国程序化报备与异常交易监控（见 <a href="/quant/cn-quant-regulation-history">中国量化监管史</a>）、加密市场的商业性做市协议。逐域对照是另一门课，本课给的是把制度翻译成引擎约束与监控指标的方法。</p>',11)),(e(),n(o,null,{default:A(()=>[i(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INC%5B%22%E6%BF%80%E5%8A%B1%EF%BC%9A%E5%9B%9E%E6%89%A3%E3%80%81%E8%B4%B9%E5%87%8F%E3%80%81%E5%9C%B0%E4%BD%8D%22%5D%20--%3E%20OBL%5B%22%E4%B9%89%E5%8A%A1%EF%BC%9A%E4%BB%B7%E5%B7%AE%E3%80%81%E5%9C%A8%E5%B8%82%E3%80%81%E8%A7%84%E6%A8%A1%22%5D%0A%20%20OBL%20--%3E%20ENG%5B%22%E5%BC%95%E6%93%8E%E7%A1%AC%E7%BA%A6%E6%9D%9F%EF%BC%9A%E9%A2%84%E6%A3%80%E8%A7%84%E5%88%99%22%5D%0A%20%20RED%5B%22%E7%BA%A2%E7%BA%BF%EF%BC%9A%E8%99%9A%E5%81%87%E6%B5%81%E5%8A%A8%E6%80%A7%E3%80%81%E6%8A%A2%E8%B7%91%22%5D%20--%3E%20ENG%0A%20%20ENG%20--%3E%20QUOTE%5B%22%E6%8A%A5%E4%BB%B7%22%5D%0A%20%20QUOTE%20--%3E%20MON%5B%22%E7%9B%91%E6%8E%A7%EF%BC%9A%E5%9C%A8%E5%B8%82%E7%8E%87%E3%80%81%E5%AE%BD%E5%BA%A6%E5%90%88%E8%A7%84%E7%8E%87%E3%80%81%E6%92%A4%E5%8D%95%E7%8E%87%22%5D%0A%20%20MON%20--%3E%20LOG%5B%22L3%20%E6%97%A5%E5%BF%97%E4%B8%8E%E5%8E%9F%E5%9B%A0%E7%A0%81%E7%95%99%E5%AD%98%22%5D%0A%20%20LOG%20--%3E%20AUDIT%5B%22%E8%81%94%E5%90%88%E8%AF%84%E5%AE%A1%E8%BF%9B%E5%8F%B0%E8%B4%A6%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"义务的经济学是公共品：连续性与价格发现无法由分散的使用者分别付费，市场设计者用集中激励换义务供给。义务的形状由此而定：挑做市商本来就要做的事设下限，而不是指挥策略。张力也由此而来：毒性最高、最想收手的时刻，恰是义务价值最大的时刻——第五到第七课的「档位」设计，就是在义务边界内重新获得自由。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"数字实例：合同要求在市时间比例 \\(95\\%\\)，一个月约 \\(22\\) 个交易日、每天 \\(6.5\\) 小时，合计约 \\(8580\\) 分钟，缺席额度只有 \\(5\\%\\approx 429\\) 分钟。毒性高峰里「全撤半小时冷静一下」，一次就烧掉约 \\(7\\%\\) 的额度——这就是为什么停报要按预算精打细算地花，而不是想停就停。")],-1)),(e(),n(o,null,{default:A(()=>[i(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E6%AF%92%E6%80%A7%E6%A3%80%E6%B5%8B%E8%A7%A6%E5%8F%91%22%5D%20--%3E%20C%5B%22%E4%B9%89%E5%8A%A1%E7%BA%A6%E6%9D%9F%EF%BC%9A%E5%9C%A8%E5%B8%82%E7%8E%87%E3%80%81%E5%AE%BD%E5%BA%A6%E4%B8%8A%E9%99%90%E3%80%81%E6%9C%80%E5%B0%8F%E8%A7%84%E6%A8%A1%22%5D%0A%20%20C%20--%3E%20O1%5B%22%E6%A1%A3%E4%BD%8D%E4%B8%80%EF%BC%9A%E6%94%B6%E7%AA%84%E5%88%B0%E4%B9%89%E5%8A%A1%E5%AE%BD%E5%BA%A6%E4%B8%8B%E9%99%90%22%5D%0A%20%20C%20--%3E%20O2%5B%22%E6%A1%A3%E4%BD%8D%E4%BA%8C%EF%BC%9A%E5%8F%AA%E4%BF%9D%E6%9C%80%E5%B0%8F%E6%8C%82%E5%8D%95%E9%87%8F%22%5D%0A%20%20C%20--%3E%20O3%5B%22%E6%A1%A3%E4%BD%8D%E4%B8%89%EF%BC%9A%E5%8D%95%E4%BE%A7%E5%81%9C%E3%80%81%E5%8F%A6%E4%B8%80%E4%BE%A7%E5%AE%88%E4%B9%89%E5%8A%A1%22%5D%0A%20%20O1%20--%3E%20L%5B%22%E5%8A%A8%E4%BD%9C%E4%B8%8E%E7%90%86%E7%94%B1%E5%86%99%E5%85%A5%20L3%20%E6%97%A5%E5%BF%97%22%5D%0A%20%20O2%20--%3E%20L%0A%20%20O3%20--%3E%20L%0A%20%20X%5B%22%E5%8F%8C%E4%BE%A7%E5%85%A8%E6%92%A4%22%5D%20--%3E%20Z%5B%22%E4%B8%8D%E5%8F%AF%E9%80%89%EF%BC%9A%E8%BF%9D%E5%8F%8D%E5%9C%A8%E5%B8%82%E4%B9%89%E5%8A%A1%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=B('<p>红线的技术面在意图与模式的边界：做市修订与虚假申报用同一套接口、同一个撤单按钮，区分只能靠模式证据与留痕。美国的 spoofing 禁令 2010 年写入成文法，首个刑事定罪在 2015 年——「挂了再撤」从惯例问题变成刑责问题。合规的可行解不是少撤单，而是每笔撤单都有可回放的理由。</p><p><span class="marginnote">常见误区：初学者以为合规就是「少撤单」。实际上虚假申报认定看的是<strong>意图与模式</strong>——为制造深度假象而挂撤才叫 spoofing，正常的风险撤销不在其列。为了少撤单硬扛毒性流，亏损会先爆炸；可行解是把每笔撤单的理由留痕到可回放，而不是不敢撤。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>熔断与波动中断时段义务可暂停或转换，复开批次里的在市语义要按<a href="/quant/circuit-breaker-design">熔断设计</a>预先定义。跨制度经营从严者适用。本课不是法律意见：具体义务以交易所规则、做市协议与监管文本为准，写作口径为据公开文本与 Harris 教材整理。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>义务做市是激励换供给：价差、在市、规模义务对应回扣与地位；红线是合同与法律的双重边界。</li><li>义务作为硬约束进引擎，与限额同一接口；毒性防御在义务角落里选档位。</li><li>自证靠 L3 日志与原因码：每笔撤单可回放理由，是合规基础设施。</li><li>撤单流有两个读者：风险管理语言与监管语言并存，指标必须能同时回答两者。</li><li>制度差异翻译成引擎约束与监控指标；逐域对照是另一门课。</li><li>出处：Harris, <em>Trading and Exchanges</em>, 2003；Dodd–Frank Act 对商品交易法的 spoofing 修正（2010）；中国程序化报备口径见 <a href="/quant/cn-quant-regulation-history">中国量化监管史</a>。</li></ul>',6))])}const g=l(p,[["render",m]]);export{c as __pageData,g as default};
